/* Posts use the commander profile name, including existing V22 history.
 * Renaming the profile updates the display name throughout its local feeds. */
#include <psprtc.h>
static const char *social_lines[SB_COUNT-1][SOCIAL_VARIANTS]={{"%s just arrived. Welcome! Please don't trust the free parking beacon.","%s just dropped out of witchspace. Kettle's on, Commander.","%s is in the lanes. Another pilot about to discover our docking queue.","Oh good, %s arrived. Another person who thinks the whole docking lane is theirs.","%s is here. Alert the gift shop. Or don't. I'm not your supervisor.","New arrival: %s. Nobody clap, you'll encourage them.","Welcome, %s. If anyone offers you free fuel, count your kidneys afterwards.","%s arrived and my delivery still hasn't. Thrilled for one of us."},{"Watched %s jump out. There goes my favourite moving window reflection.","%s left the system. Safe travels, mysterious engine noise.","%s is off the traffic board. Hope they packed snacks for the jump.","%s jumped out. At last, some peace on this bloody frequency.","Safe journey, %s. Space is enormous. Feel free to explore lots of it.","%s has left. Taking bets on how long before they're back for snacks.","There goes %s. Quite like watching departures, actually.","%s departed. This is not an airport. Except technically it sort of is."},{"%s just docked. Somewhere a cargo trolley is about to have a very busy day.","Caught %s coming into port. My coffee survived. Five stars.","%s is in the berth. Whoever's meeting them: stop blocking the lift.","%s docked. We can all stop pretending the arrival board is exciting.","%s is in port. Someone hide the awful souvenir mugs.","Another berth occupied by %s. My thrilling evening continues.","Glad you made it in, %s. Long flights can be rough.","%s docked. Congratulations on finding the giant building."},{"Saw %s leave port into the sunlight. Almost made my shift feel cinematic.","%s just launched. I waved from the window. They probably saw a tiny blob.","Port doors, engine glow, %s departing. Better than the bar's broken holo-screen.","%s launched. Yes, mate, we can all see your spaceship.","Off goes %s. I'd go too, but my ship is mostly unpaid invoices.","%s leaving port looked lovely against the sun. There, I said something nice.","%s launched. Whoever sold me these earplugs owes me money.","%s is out of the berth. Finally, my favourite view: an empty parking space."},{"Did anyone else see Law escort %s into custody? Awkward day to be on the local feed.","%s got taken into custody. Please stop asking me for the arrest footage.","Law took in %s. I'm not guessing why. Half this feed already is.","%s in custody. Spectacular way to ruin your afternoon, you muppet.","Law took %s in. Feed detectives: you don't know the charges. Shut up.","Not laughing at %s getting arrested. All right, a little.","%s got arrested. Hope they're treated properly, whatever happened.","%s in custody and half the station suddenly has a law degree."},{"%s paid the fine and got released. An expensive way to meet the neighbours.","Law let %s go after payment. I would need three shifts and a bake sale.","Fine settled, %s moving again. Turns out the universe does accept invoices.","%s paid the fine. An idiot tax with very official stationery.","Warrant settled for %s. Lovely. Can we move on now?","%s paid up. My wallet flinched in sympathy.","Fine paid, %s released. Try a less expensive hobby next time.","%s settled with Law. That's between them and their bank balance."},{"%s ran from Law. This is why my insurance application has extra pages.","Saw %s break away from a patrol stop. Absolutely not joining that chase.","Law is chasing %s. My advice: don't livestream while flying.","%s ran from Law. Brilliant, genius. Surely that fixes everything.","Saw %s flee the patrol. That plan has all the elegance of a kicked bin.","%s is being pursued. Please keep that nonsense away from the freight lanes.","I'm not cheering for %s or the patrol. I'm cheering for nobody hitting my ship.","%s fled. Going to be a hell of an awkward return to port."},{"%s took down a pirate. Freight crews can breathe a little easier.","One fewer pirate thanks to %s. I'd buy the pilot a drink if I wasn't broke.","Saw %s finish a wanted contact. Brave flying. I'll keep hauling biscuits.","%s took down a pirate. Good work. Please don't become unbearable about it.","Pirate down, courtesy of %s. My cargo and I appreciate that.","%s got a pirate. Cue three hours of cockpit bragging.","A pirate lost to %s today. That's got to sting.","Credit where due: %s made this route a little less miserable."},{"%s destroyed a ship out here. Keep your distance; this isn't a fireworks show.","A ship went down to %s. Hope the escape systems worked. Lanes feel colder now.","Destruction on the scope, %s involved. Not posting jokes about that one.","%s destroyed a ship. Bloody awful thing to watch on a scanner.","Another ship destroyed by %s. Don't turn the wreckage into a tourist stop.","Not celebrating that ship going down to %s. Someone was flying it.","%s destroyed a contact. The armchair admirals are already arguing.","Ship destroyed, %s involved. We need facts, not your heroic fan fiction."},{"%s got new ship paint! That finish looks fantastic under dock lights.","Who repainted %s's ship? Mine suddenly looks like a rented toolbox.","%s's ship got a fresh coat. Budget says fuel. Heart says shiny spaceship.","%s paid for that paint? With actual money? Incredible.","New finish on %s's ship. Looks like a sweet wrapper with an engine.","I like %s's new paint. Yes, I have terrible taste. Both can be true.","%s repainted. Still the same pilot underneath, unfortunately.","%s got new paint and apparently we're all meant to stop working and admire it."},{"%s just bought a new ship. Imagine having new-ship money instead of new-socks money.","Spotted %s collecting a new ship. Hope it has that new cockpit smell.","%s left the showroom with a new ship. That first scratch is going to hurt.","%s bought a new ship. You can't buy talent, but you can buy more buttons.","New ship for %s. That sales rep has absolutely earned their commission.","%s changed ships. Hope the seat isn't sticky. That's my whole buying checklist.","Good for %s getting a new ship. Genuinely. Mine smells like warm socks.","%s bought another hull. Lovely. Does it come with a personality?"},{"Surface traffic logged %s landing. Boots on dirt beats another night by a vending machine.","%s made planetfall. Bring back a rock. No, a different rock.","%s is down on a landing pad. Time to remember how walking works.","%s made planetfall. The ground has my sympathies.","%s landed. Great. Go touch some actual grass, if the planet has any.","Happy landing, %s. Check the atmosphere before getting sentimental.","%s is on the surface. Finally, a chance to stretch something besides a fuel budget.","%s landed and I am still staring at a bulkhead. Not jealous. Much."},{"%s logged local plant life. Finally, someone checking whether the bushes bite.","New flora notes from %s. Botany is cooler when you arrive by spaceship.","%s uploaded plant surveys. My windowsill fungus demands equal recognition.","%s scanned a plant. The plant declined to comment.","Botany update from %s. Finally using the scanner for something that won't shoot back.","%s logged flora. Please don't start calling yourself a tree whisperer.","Plant notes from %s. Useful work, even if nobody writes songs about it.","%s found plants. My lunch found mould. We're basically colleagues."},{"%s sent in fauna observations. Sensible. I would just ask everything if it's friendly.","Wildlife notes uploaded by %s. Please don't bring a souvenir with teeth.","%s is cataloguing animals. Somebody has to ask the important questions: legs? how many?","%s logged wildlife. Wonder what the wildlife wrote about them.","Animal survey from %s. 'Annoying biped with scanner' is probably the review in return.","%s scanned fauna. Sensible to look rather than poke it, for once.","New wildlife notes from %s. More of this, less shooting things.","%s is studying animals. At least one creature out there must be equally confused."},{"%s scanned a stellar rift. I'd like the pretty lights without the existential questions.","Rift data from %s hit the survey archive. Space remains aggressively weird.","%s went close enough to log a rift. I'm admiring it from a responsible distance.","%s scanned a rift. Space already looks broken enough without close-ups.","Rift report from %s. Read it. Understood roughly four words.","%s logged a rift. No, that does not make you a wizard.","Glad %s is investigating those things. I'd rather somebody else did it.","%s scanned the weird glow. My scientific opinion remains: absolutely not."},{"Watched %s tractor loose salvage aboard. Cosmic tidying. With engines.","%s is recovering debris. One pilot's wreckage is another pilot's repair budget.","Salvage hauled in by %s. I can't even pick up a sock with the cabin grabber.","%s recovered salvage. Finally, a bin collector with a hyperdrive.","More debris collected by %s. Filthy work, respectable money.","%s is hauling salvage. I hope that smell stays inside their hold.","Salvage aboard for %s. Space is not short of other people's crap.","%s collected wreckage. Better than leaving it for my windscreen."},{"Another contract completed by %s. Meanwhile I haven't answered one message.","Mission office marked %s's job complete. Quietly getting things done.","%s finished a contract. Nice to see a promise turn into a paid invoice.","%s completed a job. Bare minimum achieved. Parade cancelled.","Contract finished by %s. Reliable people are rarer than shiny ships.","%s got paid for a completed job. Must be nice.","Job done for %s. Please send the invoice to literally anyone but me.","%s finished a contract. Another client spared the phrase 'nearly there'."},{"Was just wondering where %s had gone. The lanes have felt oddly quiet lately.","Haven't seen %s for a while. Hope they found something worth the fuel.","Anyone seen %s lately? I miss watching their ship pass the window.","Haven't seen %s lately. Not a complaint. Just enjoying the silence.","Where's %s got to? Someone else has to be the local pain in the arse now.","Anyone heard from %s? Jokes aside, hope they're all right.","%s hasn't been around. The departure lounge has nobody new to gossip about.","Been a while since %s checked in. I refuse to admit I noticed."},{"%s is back! Welcome home-ish. We kept absolutely none of your parking space.","%s checked in again. Good to see a familiar name on the local wire.","%s returned! Night shift feels less lonely with familiar company.","%s is back. There goes the neighbourhood.","Welcome back, %s. We had a lovely quiet spell. Thanks for ending it.","%s returned! I owe someone five units. Don't ask why.","Oh, %s again. Didn't we just get this place tidy?","Good to hear from %s again. Space gets lonely, even for sarcastic bastards."},{"My kettle has more warning lights than my ship. Should I be worried?","Personal ad: seeks copilot. Must enjoy long silences and identifying suspicious rattles.","Dock cafe review: the soup has escaped its bowl again. Four stars for ambition.","Selling one 'reliable' engine. The quotation marks are included in the price.","Whoever microwaved fish in Dock Six: the vacuum is right there.","My copilot says I complain too much. Anyway, here's a list of their faults.","Unpopular opinion: your ship doesn't need more lights. It needs washing.","Looking for love. Or affordable coolant. Honestly, either would do."}};
/* Sixteen tone-matched codas combine with every authored event line.  This
 * yields 20 * 8 * 16 = 2,560 post bodies without bloating the save format. */
static const char *social_tails[3][SOCIAL_TAIL_VARIANTS]={
 {"The night shift noticed.","The comments are divided.","Dock Six has opinions.","That's going in the group chat.","My copilot called it inevitable.","Honestly, fair enough.","The canteen is discussing it.","Someone owes me five units.","No further questions, please.","Space remains deeply unserious.","That made the late bulletin.","The local wire never sleeps.","I blame the docking computer.","This concludes my report.","Anyway, carry on.","Nobody asked, but there it is."},
 {"Hope nobody else was hurt.","That could have ended worse.","Keep clear of the wreckage.","Law channels are still busy.","Nobody needs another replay.","The facts are still coming in.","Fly carefully around there.","Somebody had a rotten shift.","Not a story I'd joke about.","The lanes feel quieter now.","Insurance crews are thrilled.","Leave the armchair lawyering.","Maybe log off for five minutes.","The station is still arguing.","That was ugly on the scope.","Let's not make this a trend."},
 {"Credit where it's due.","Useful work for once.","The night crew approves.","That deserves a quiet cheer.","Put it in the station log.","Someone buy them a drink.","The archive needed that.","More of this, please.","Even Dock Six noticed.","Not bad for one shift.","The canteen seems impressed.","That made the good bulletin.","My copilot approves.","Actual progress. Imagine that.","Fly safe and spend the payout.","Nice work, no grandstanding."}
};
static int social_tone(unsigned kind){
 if(kind==SB_ARREST||kind==SB_FLEE||kind==SB_DESTROY)return 1;
 if(kind==SB_BOUNTY||kind==SB_FLORA||kind==SB_FAUNA||kind==SB_RIFT||kind==SB_SALVAGE||kind==SB_JOB)return 2;
 return 0;
}
static void social_name(char *out,int size,const char *name){
 int word=1,i=0;for(;name[i]&&i<size-1;i++){unsigned char c=name[i];
 if(c>='A'&&c<='Z')c+='a'-'A';
 if(word&&c>='a'&&c<='z')c-='a'-'A';
 out[i]=(char)c;word=(c==' '||c=='-'||c=='\'');
 }out[i]=0;
}
static int social_count(void){return (int)game.social.count;}
static int social_offset(void){return tutorial_active(&game)?1:0;}
static int social_event_row(int r){int i=r-social_offset();return i>=0&&i<social_count()?i:-1;}
static int social_rows(void){int n=social_count()+social_offset();return n?n:1;}
static unsigned social_code(int r){int i=social_event_row(r);return i>=0?game.social.post[i]:0;}
static void social_author(unsigned seed,char *out,int size){
 static const char *a[]={"Nebula","Cosmic","Soggy","Quantum","Disco","Void","Turbo","Sleepy","Lunar","Unpaid","Sneaky","Velvet","Radioactive","Orbital","Space","Neon"};
 static const char *b[]={"Noodle","Moth","Turnip","Goblin","Badger","Kettle","Gecko","Janitor","Toast","Comet","Grandad","Socks","Gremlin","Pigeon","Spanner","Banana"};
 snprintf(out,size,"%s%s_%02u",a[seed&15],b[(seed>>4)&15],(seed>>8)%100);
}
static void social_post_text(unsigned code,int legacy,char *author,int alen,char *body,int blen){
 unsigned seed=(code>>9)&0x1fffff,kind=code&31,ship=(code>>5)&15;
 social_author(seed,author,alen);
 if(kind<1||kind>=SB_COUNT||ship>=(unsigned)player_ship_count){snprintf(body,blen,"Post unavailable.");return;}
 char name[25];social_name(name,sizeof(name),game.commander_name);
 if(legacy){snprintf(body,blen,social_lines[kind-1][seed%3],name);return;}
 char event[150];snprintf(event,sizeof(event),social_lines[kind-1][seed%SOCIAL_VARIANTS],name);
 snprintf(body,blen,"%s %s",event,social_tails[social_tone(kind)][(seed/SOCIAL_VARIANTS)%SOCIAL_TAIL_VARIANTS]);
}
static int social_reaction(int r){
 unsigned code=social_code(r);if(code)return code>>30;
 return social_offset()&&r==0?(int)game.social.evidence_reaction:0;
}
static void social_react(int r,int value){
 if(social_reaction(r)==value)value=0;
 int i=social_event_row(r);
 if(i>=0)game.social.post[i]=(game.social.post[i]&0x3fffffffu)|((unsigned)value<<30);
 else if(social_offset()&&r==0)game.social.evidence_reaction=(unsigned)value;
}
static void social_date(int r,char *out,int size){
 int i=social_event_row(r);if(i<0){snprintf(out,size,"Pinned story");return;}
 uint32_t stamp=game.social.stamp[i];
 if(stamp&0x80000000u){snprintf(out,size,"%.12s / date unavailable",game.systems[game.social.origin[i]&255].name);return;}
 ScePspDateTime d,epoch={1970,1,1,0,0,0,0};u64 base=0;
 if(sceRtcGetTick(&epoch,&base)<0){snprintf(out,size,"Clock unavailable");return;}
 u64 tick=base+(u64)stamp*sceRtcGetTickResolution();
 if(sceRtcSetTick(&d,&tick)<0){snprintf(out,size,"Clock unavailable");return;}
 snprintf(out,size,"%04d-%02d-%02d %02d:%02d UTC / %.12s",d.year,d.month,d.day,d.hour,d.minute,game.systems[game.social.origin[i]&255].name);
}
